#include "../lab/QueryProcessing/mergeSort.h"

using namespace std;

// dump a chain of two-attribute tuples starting at addr
static void dumpChain(Buffer *buf, unsigned int addr, const char *label)
{
	cout << "CHAIN " << label << " @" << addr << endl;
	int n = 0, blocks = 0;
	while (addr != 0) {
		unsigned char *blk = readBlockFromDisk(addr, buf);
		if (!blk) { cout << "  MISSING BLOCK " << addr << endl; return; }
		Relation t[TUPLE_PER_BLK];
		readTuplesFromBlock(blk, t);
		unsigned int next;
		memcpy(&next, blk + buf->blkSize - PTR_SIZE, PTR_SIZE);
		cout << "  blk " << addr << ":";
		for (int i = 0; i < TUPLE_PER_BLK; i++) {
			if (t[i].attr1 == 0) continue;
			cout << " (" << t[i].attr1 << "," << t[i].attr2 << ")";
			n++;
		}
		cout << " next=" << next << endl;
		freeBlockInBuffer(blk, buf);
		blocks++;
		addr = next;
		if (blocks > 200) { cout << "  RUNAWAY CHAIN" << endl; break; }
	}
	cout << "  tuples=" << n << " blocks=" << blocks << endl;
}

int main(int argc, char **argv)
{
	string what = argc > 1 ? argv[1] : "sort";
	Buffer buf;
	if (!initBuffer(BUF_SIZE, BLK_SIZE, &buf)) return 1;

	if (what == "sort") {
		int io = mergeSort(&buf, SORT_R);
		cout << "mergeSort(R) io=" << io << " numIO=" << buf.numIO << endl;
		dumpChain(&buf, MERGE_R_RET_ADDR, "sorted R");
		Buffer buf2;
		initBuffer(BUF_SIZE, BLK_SIZE, &buf2);
		io = mergeSort(&buf2, SORT_S);
		cout << "mergeSort(S) io=" << io << " numIO=" << buf2.numIO << endl;
		dumpChain(&buf2, MERGE_S_RET_ADDR, "sorted S");
		cout << "free blocks after: R=" << buf.numFreeBlk << " S=" << buf2.numFreeBlk
		     << " (of " << buf.numAllBlk << ")" << endl;
		freeBuffer(&buf2);
	} else if (what == "runs") {
		mergeSort(&buf, SORT_R);
		for (int s = 0; s < 2; s++)
			dumpChain(&buf, MERGE_R_SEG_ADDR + s * 8, "run");
	}

	freeBuffer(&buf);
	return 0;
}
