32	void parseQuery(TreeNode *root, string query)
33	{
34		// get tokens seperated by space
35		vector<string> token;
36		string temp = "";
37		for (int i = 0; i < query.length(); i++) {
38			if (query[i] == ' ') {
39				token.push_back(temp);
40				temp = "";
41			} else {
42				temp += query[i];
43			}
44		}
45	
46		// parse
47		TreeNode *p = root;
48		auto it = token.begin();
49		while (it != token.end()) {
50			if (*it == "[") {
51				it++;
52				string info = "";
53				while (*it != "]") {
54					info += *it;
55					it++;
56				}
57				p->info = info;
58				it++; // it points to "]".next now
59			} else if (*it == "(") {
60				it++;
61				if (*it == "SELECT" || *it == "PROJECTION") {
62					TreeNode *q = new TreeNode(*it);
63					p->left = q;
64					p = q;
65					it++;
